-- JSOS 40-theme curriculum v2.0. Each theme owns stable, selectable scenes.
-- Preserve templates referenced by existing tasks, but move the prior ordering
-- out of the way and disable entries that are no longer part of v2.0.
with order_offset as (
  select coalesce(max(abs(original_order)), 0) + 1000 as value
  from public.curriculum_templates
)
update public.curriculum_templates
set original_order = original_order + order_offset.value,
    enabled = false
from order_offset;

on conflict (stable_key) do update set
  original_order = excluded.original_order,
  stage = excluded.stage,
  topic = excluded.topic,
  scenario = excluded.scenario,
  target_patterns = excluded.target_patterns,
  enabled = true;
